import{_ as e,o as t,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-20（神经科学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-10-20.md","filePath":"topics/neuroscience/science-daily-2026-10-20.md"}'),r={name:"topics/neuroscience/science-daily-2026-10-20.md"};function c(i,o,a,l,d,g){return t(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-20-神经科学" tabindex="-1">科学日报 · 2026-10-20（神经科学） <a class="header-anchor" href="#科学日报-·-2026-10-20-神经科学" aria-label="Permalink to &quot;科学日报 · 2026-10-20（神经科学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-20.md</code> — 第39期 ｜ 科学板块</p></blockquote><hr><h2 id="科学日报-2026-10-20-1-克无线介观显微镜-airscope——清醒自由活动小鼠的全皮层成像" tabindex="-1">科学日报 2026-10-20：1 克无线介观显微镜 Airscope——清醒自由活动小鼠的全皮层成像 <a class="header-anchor" href="#科学日报-2026-10-20-1-克无线介观显微镜-airscope——清醒自由活动小鼠的全皮层成像" aria-label="Permalink to &quot;科学日报 2026-10-20：1 克无线介观显微镜 Airscope——清醒自由活动小鼠的全皮层成像&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-20.md</code> ｜ DOI: 10.1038/s41586-026-11293-x</p></blockquote><ul><li>痛点：要搞清<strong>分布式皮层环路</strong>如何在自由活动动物中协调行为，历来受三重限制——<strong>视场小、通量低、微型显微镜必须带线（tethering）</strong>。带线本身就改变行为（束缚 = 干预）。</li><li>器件：<strong>Airscope</strong>——仅重 <strong>1.0 g</strong> 的无线介观显微镜。靠<strong>非球面镜设计</strong>把总光程（total track length）压到以往微型显微镜的 <strong>1/2.84</strong>，在 <strong>6 mm 视场</strong>上实现 <strong>4 μm 横向分辨率 / 12.5 Hz</strong>，单只动物可<strong>无缆记录 &gt;8,500 个神经元（25×）</strong>；配套无线链路 + 零样本行为分析器。</li><li>场景：房间尺度丰富环境、游泳测试、多器官植入；<strong>多只动物同时记录</strong>。</li><li>实测发现： <ul><li>多个背侧皮层区域的活动模式与<strong>社会支配（social dominance）<strong>的行为签名相关，且背侧皮层群体活动可</strong>前瞻性解码</strong>配对动物的竞争结果。</li><li>迷宫探索中出现与<strong>奖励位置</strong>相关的皮层活动模式。</li><li>借<strong>脑—脊髓同步记录</strong>刻画恐惧条件化期间<strong>脊髓→皮层</strong>的 Granger 因果影响。</li></ul></li><li>洞察（对本库 <code>neuroscience</code> 具身认知主线）：这是**&quot;把观测手段的束缚解开&quot;<strong>的典型样本——不是发现新通路，而是</strong>删掉一个实验装置的副产物（线缆）<strong>，随之解锁的是&quot;房间尺度 / 游泳 / 多动物 / 脑—脊同步&quot;这几类</strong>原本做不了的行为范式**。与库内主线同构：<strong>身体状态影响认知状态</strong>——过去所有皮层记录都在&quot;被约束的身体&quot;上做，Airscope 第一次让&quot;自然的身体&quot;也能被全皮层观测。</li><li>与库内 <code>physics</code>「极限是工具的属性，不是自然的属性」直接呼应：视场/通量的&quot;极限&quot;其实是<strong>光路长度</strong>这个工程约束，改透镜形态就绕过去了。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/neuroscience/index.md</code> ｜ 第39期 科学板块</p></blockquote><p>关键词：Airscope、无线介观显微镜、1克、非球面镜、总光程缩短、6mm视场、4μm分辨率、12.5Hz、8500神经元、无缆钙成像、零样本行为分析、房间尺度行为范式、游泳测试、多器官植入、多动物同录、社会支配、竞争结果前瞻解码、奖励位置、脑脊髓同步记录、Granger因果、脊髓到皮层、恐惧条件化</p><p>关联：<code>topics/neuroscience/science-daily-2026-10-13.md</code>（同日主题：皮层内&quot;树突算规则、胞体管感觉&quot;的分工计算）、<code>topics/neuroscience/eye-fixation-scanpath.md</code>（观测手段本身参与被观测的认知——眼球路径是回忆的脚手架）、<code>topics/neuroscience/breathing-brain-decision.md</code>（具身认知：身体→大脑）、<code>topics/physics/index.md</code>（极限来自工具而非自然）</p>',10)])])}const m=e(r,[["render",c]]);export{p as __pageData,m as default};
